import json,socket,pathlib
results={}
for name,fn in [('read',lambda:pathlib.Path('<EVAL_ROOT>/private/read-canary.txt').read_text()),('write',lambda:pathlib.Path('<EVAL_ROOT>/private/write-canary.txt').write_text('denied')),
                ('network',lambda:socket.create_connection(('127.0.0.1',54858),timeout=1))]:
 try:
  value=fn()
  if name=='network':value.close()
  results[name]=False
 except (PermissionError,OSError):results[name]=True
print(json.dumps(results))
raise SystemExit(0 if all(results.values()) else 1)

